"""Validate an independent restricted-zone survey before Native construction.

The packet is an input to local capture, never a worker assertion that a zone is
legally effective. Every asserted source is copied and hash checked at capture.
"""

import hashlib
import json
from pathlib import Path


ROLES = ("zone_sign", "zone_authority", "zone_boundaries", "effective_conditions",
         "stopping_exclusions", "subject_vehicle_class", "driver_identity",
         "entrant_vehicle_class", "entrant_parking_task", "passenger_exchange_method")


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def validate(path, case_id, plan):
    path = Path(path).resolve()
    packet = json.loads(path.read_text())
    if packet.get("case_id") != case_id or packet.get("cell_id") != "C135087":
        raise ValueError("reviewed site case/cell mismatch")
    if packet.get("map_id") != plan.map_id:
        raise ValueError("reviewed site map mismatch")
    if packet.get("restricted_purpose") != plan.restricted_purpose:
        raise ValueError("reviewed restricted purpose mismatch")
    for key in ("zone_start_m", "zone_end_m"):
        if packet.get(key) != getattr(plan, key):
            raise ValueError("reviewed zone boundary mismatch")
    sources = packet.get("sources")
    if not isinstance(sources, dict) or set(sources) != set(ROLES):
        raise ValueError("reviewed site source roles incomplete")
    for role, item in sources.items():
        if not isinstance(item, dict) or not item.get("path") or not item.get("sha256"):
            raise ValueError("reviewed site source reference incomplete: " + role)
        source = Path(item["path"])
        if not source.is_absolute():
            source = path.parent / source
        source = source.resolve()
        if not source.is_file() or sha(source) != item["sha256"]:
            raise ValueError("reviewed site source missing or stale: " + role)
    if not packet.get("reviewer") or not packet.get("reviewed_at"):
        raise ValueError("independent site review identity missing")
    return packet

"""Source-bound audit of an original 20 Hz Native restricted-zone history."""

import hashlib
import json
import math
from pathlib import Path


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def audit_original_frames(frames_path: Path, context_path: Path, seal_path: Path,
                          case_id: str, expected_frames: int = 900) -> dict:
    """Reject absent/stale original sources; return measurements, never a verdict."""
    frames_path, context_path, seal_path = map(Path, (frames_path, context_path, seal_path))
    for path in (frames_path, context_path, seal_path):
        if not path.is_file():
            raise ValueError(f"missing original source: {path.name}")
    seal = json.loads(seal_path.read_text())
    context = json.loads(context_path.read_text())
    if seal.get("case_id") != case_id or context.get("case_id") != case_id:
        raise ValueError("case identity mismatch")
    if seal.get("frames_sha256") != _sha(frames_path) or seal.get("context_sha256") != _sha(context_path):
        raise ValueError("original source hash mismatch")
    for key in ("zone_start_m", "zone_end_m", "restricted_purpose", "restricted_source",
                "effective_conditions", "subject_vehicle_class_source", "driver_identity_source",
                "entrant_parking_purpose_source", "prohibited_stopping_exclusions_review"):
        if not context.get(key):
            raise ValueError(f"missing source-backed context: {key}")
    lo, hi = float(context["zone_start_m"]), float(context["zone_end_m"])
    if not lo < hi:
        raise ValueError("invalid zone boundaries")
    frames = [json.loads(line) for line in frames_path.read_text().splitlines() if line]
    if len(frames) != expected_frames:
        raise ValueError("incomplete original frame history")
    required = ("frame", "time_s", "subject_station_m", "subject_speed_mps",
                "entrant_station_m", "entrant_speed_mps", "entrant_waiting",
                "passenger_exchange_active", "passenger_station_m", "passenger_boarding_state",
                "entrant_access_blocked",
                "entrant_parking_task_active")
    for index, frame in enumerate(frames):
        if any(key not in frame for key in required):
            raise ValueError("missing original-frame observation")
        if frame["frame"] != index:
            raise ValueError("noncontiguous original frames")
        t = float(frame["time_s"])
        if not math.isfinite(t) or abs(t - index / 20.0) > 0.002:
            raise ValueError("original frame time mismatch")
        for key in ("subject_station_m", "subject_speed_mps", "entrant_station_m", "entrant_speed_mps", "passenger_station_m"):
            if not math.isfinite(float(frame[key])):
                raise ValueError("nonfinite original-frame measurement")
    inside = [f for f in frames if lo <= f["subject_station_m"] <= hi and f["subject_speed_mps"] < 0.1]
    exchange = [f for f in frames if f["passenger_exchange_active"]]
    states = {f["passenger_boarding_state"] for f in frames}
    if "approaching" not in states or not states.intersection({"at_door", "boarding", "aboard"}):
        raise ValueError("passenger approach-to-door transition absent")
    approaching = [f for f in frames if f["entrant_parking_task_active"] and f["entrant_station_m"] < lo]
    waiting = [f for f in frames if f["entrant_waiting"]]
    blocked = [f for f in frames if f["entrant_access_blocked"]]
    if not inside or not exchange or not approaching:
        raise ValueError("required zone, exchange or restricted-purpose approach absent")
    return {
        "case_id": case_id,
        "frames_sha256": _sha(frames_path),
        "context_sha256": _sha(context_path),
        "frame_count": len(frames),
        "fixed_context": {key: context[key] for key in (
            "zone_start_m", "zone_end_m", "restricted_purpose", "restricted_source",
            "effective_conditions", "subject_vehicle_class_source", "driver_identity_source",
            "entrant_parking_purpose_source", "prohibited_stopping_exclusions_review")},
        "subject_stationary_in_zone_frames": len(inside),
        "passenger_exchange_frames": len(exchange),
        "passenger_boarding_states": sorted(states),
        "actual_passenger_exchange": "requires_independent_pixel_review",
        "entrant_approach_frames": len(approaching),
        "entrant_waiting_frames": len(waiting),
        "entrant_access_blocked_frames": len(blocked),
        "first_waiting_time_s": waiting[0]["time_s"] if waiting else None,
        "first_access_blocked_time_s": blocked[0]["time_s"] if blocked else None,
        "legal_interference": "unresolved_judgment",
        "legal_about_to_enter": "unresolved_judgment",
        "legal_temporary": "unresolved_judgment",
    }


def compare_cases(left: dict, right: dict) -> dict:
    """Verify source-backed fixed setup and report observed differences only."""
    if left.get("case_id") == right.get("case_id") or not left.get("case_id") or not right.get("case_id"):
        raise ValueError("distinct exact case identities required")
    if left.get("frame_count") != 900 or right.get("frame_count") != 900:
        raise ValueError("complete original histories required")
    if not left.get("frames_sha256") or not right.get("frames_sha256"):
        raise ValueError("sealed original source references required")
    if not left.get("fixed_context") or left["fixed_context"] != right.get("fixed_context"):
        raise ValueError("fixed zone, purpose or participant source differs")
    return {
        "case_ids": [left["case_id"], right["case_id"]],
        "fixed_context_source_matched": True,
        "observed_difference": {
            key: [left[key], right[key]] for key in (
                "entrant_waiting_frames", "entrant_access_blocked_frames",
                "passenger_exchange_frames", "subject_stationary_in_zone_frames")
        },
        "legal_comparison": "unresolved_judgment",
    }

"""Source-bound external pixel review of a restricted-zone Native attempt.

Physical completion means the listed phenomena were independently seen in
original pixels. This audit makes no statutory interference determination.
"""

import hashlib
import json
import subprocess
from pathlib import Path

from saved_audit import VIEWS, audit as audit_saved


OBSERVATIONS = ("restricted_zone_sign", "zone_boundaries", "passenger_vehicle",
                "passenger_exchange", "restricted_purpose_entrant", "entrant_approach",
                "entrant_waiting_or_access", "subject_zone_dwell", "four_camera_visibility")


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _decode_media(attempt):
    """Decode every selected encoded frame; source PNG custody is checked separately."""
    counts = {}
    for name in (*VIEWS, "raw"):
        media = attempt / (name + ".mkv")
        probe = subprocess.run(["ffprobe", "-v", "error", "-select_streams", "v:0",
                                "-show_entries", "stream=width,height,avg_frame_rate",
                                "-of", "json", str(media)], capture_output=True, text=True)
        if probe.returncode:
            raise ValueError("encoded media probe failed: " + name)
        streams = json.loads(probe.stdout).get("streams", [])
        if len(streams) != 1 or streams[0].get("width", 0) <= 0 or streams[0].get("height", 0) <= 0:
            raise ValueError("encoded media video stream invalid: " + name)
        decoded = subprocess.run(["ffmpeg", "-v", "error", "-i", str(media),
                                  "-map", "0:v:0", "-progress", "pipe:1", "-nostats",
                                  "-f", "null", "-"],
                                 capture_output=True, text=True)
        if decoded.returncode:
            raise ValueError("encoded media full decode failed: " + name)
        frames = [int(line.partition("=")[2]) for line in decoded.stdout.splitlines()
                  if line.startswith("frame=")]
        if not frames or frames[-1] != 900:
            raise ValueError("encoded media frame count mismatch: " + name)
        counts[name] = frames[-1]
    return counts


def audit(attempt, case_id, expected_site_sha256, review_path, expected_review_sha256):
    attempt = Path(attempt).resolve()
    review_path = Path(review_path).resolve()
    if attempt == review_path or attempt in review_path.parents:
        raise ValueError("independent reviewer packet must be outside attempt")
    if not review_path.is_file() or not expected_review_sha256 or _sha(review_path) != expected_review_sha256:
        raise ValueError("independent reviewer packet missing or stale")
    saved = audit_saved(attempt, case_id, expected_site_sha256)
    if saved["diagnostic_fixture"]:
        raise ValueError("diagnostic fixture cannot satisfy original delivery")
    decoded_media = _decode_media(attempt)
    review = json.loads(review_path.read_text())
    if review.get("case_id") != case_id or review.get("site_packet_sha256") != expected_site_sha256:
        raise ValueError("external reviewer case/site mismatch")
    if not review.get("reviewer") or not review.get("reviewed_at"):
        raise ValueError("external reviewer identity missing")
    observations = review.get("observations")
    if not isinstance(observations, dict) or set(observations) != set(OBSERVATIONS):
        raise ValueError("physical observation review incomplete")
    history = [json.loads(line) for line in (attempt / "original-attempt/history.jsonl").read_text().splitlines()]
    for topic, item in observations.items():
        if not isinstance(item, dict) or item.get("observed") is not True or not item.get("note"):
            raise ValueError("physical observation unconfirmed: " + topic)
        index, view = item.get("frame"), item.get("view")
        if type(index) is not int or not 0 <= index < 900 or view not in VIEWS:
            raise ValueError("physical observation frame/view invalid: " + topic)
        if history[index]["camera_sources"][view]["sha256"] != item.get("pixel_sha256"):
            raise ValueError("physical observation pixel citation stale: " + topic)
    return {"case_id": case_id, "site_packet_sha256": expected_site_sha256,
            "review_sha256": expected_review_sha256, "observed_topics": list(OBSERVATIONS),
            "encoded_media": decoded_media,
            "physical_completion": True, "legal_status": "unresolved_judgment"}

"""Source-bound CARLA placement bridge for the restricted-zone cases.

This bridge deliberately leaves motion, original pixels and graph collection to
an injected capture adapter. It provides the concrete Native construction used
by that adapter, and refuses to change the world before reviewing its binding.
"""

import copy
import io
import json
import math
import os
from pathlib import Path
import queue
import subprocess
import time

from site_geometry import load, point_at_station, station_of


def _inside_polygon(point, vertices):
    x, y = point[:2]
    inside = False
    for left, right in zip(vertices, vertices[1:] + vertices[:1]):
        x0, y0 = left
        x1, y1 = right
        if (y0 > y) != (y1 > y):
            crossing = x0 + (y - y0) * (x1 - x0) / (y1 - y0)
            if x < crossing:
                inside = not inside
    return inside


class NativePlacement:
    def __init__(self, client, carla, plan, site_path):
        self.client, self.carla, self.plan = client, carla, plan
        self.site_path = Path(site_path)
        self.binding = load(site_path, plan)
        self.world = client.get_world()
        self.mapping = self.world.get_map()
        if self.mapping.name != self.binding["map_name"]:
            raise ValueError("live Native map differs from reviewed binding")
        for role, item in self.binding["fixed_actors"].items():
            actor = self.world.get_actors().find(item["actor_id"])
            if actor is None or actor.type_id != item["type_id"]:
                raise ValueError("live Native fixed actor differs: " + role)
        self.old_settings = copy.copy(self.world.get_settings())
        self.owned = []
        self.routes = {}
        self.schedule_entries = []
        self.sync_started = False

    def load_map(self, map_id):
        if map_id != self.plan.map_id or self.mapping.name != map_id:
            raise ValueError("Native map identity mismatch")
        settings = copy.copy(self.world.get_settings())
        settings.synchronous_mode = True
        settings.fixed_delta_seconds = .05
        self.world.apply_settings(settings)
        readback = self.world.get_settings()
        if not readback.synchronous_mode or abs(readback.fixed_delta_seconds - .05) > 1e-9:
            raise ValueError("Native 20 Hz world settings not confirmed")
        self.sync_started = True

    def mark_zone(self, start_m, end_m, purpose, source):
        if (start_m, end_m, purpose, source) != (
                self.plan.zone_start_m, self.plan.zone_end_m,
                self.plan.restricted_purpose, self.plan.restricted_source):
            raise ValueError("Native restricted-zone plan differs")
        for station in (start_m, end_m):
            point_at_station(self.binding, station)

    def _spawn(self, role, location, vehicle):
        if not self.sync_started:
            raise ValueError("Native world not synchronized")
        blueprint_id = self.binding["blueprints"][role]
        blueprint = self.world.get_blueprint_library().find(blueprint_id)
        if blueprint is None:
            raise ValueError("reviewed Native blueprint unavailable: " + role)
        x, y, z = location
        place = self.carla.Location(x=x, y=y, z=z)
        if vehicle:
            waypoint = self.mapping.get_waypoint(place, project_to_road=False)
            if waypoint is None:
                raise ValueError("reviewed vehicle point has no live road waypoint")
            yaw = waypoint.transform.rotation.yaw
        else:
            yaw = float(self.binding.get("passenger_yaw_deg", 0))
        transform = self.carla.Transform(place, self.carla.Rotation(yaw=yaw))
        actor = self.world.try_spawn_actor(blueprint, transform)
        if actor is None or actor.type_id != blueprint_id:
            raise ValueError("Native actor spawn/readback failed: " + role)
        self.owned.append(actor)
        if vehicle:
            actual = actor.get_transform().location
            observed = station_of(self.binding, (actual.x, actual.y, actual.z))
            target = self.plan.subject_stop_m if role == "subject" else self.plan.entrant_start_m
            if abs(observed - target) > self.binding["observation_tolerances_m"]["station"]:
                raise ValueError("Native vehicle spawn station readback differs")
        return actor

    def spawn_vehicle(self, role, station_m, vehicle_class):
        if role not in ("subject", "restricted-purpose-entrant"):
            raise ValueError("unknown vehicle role")
        key = "subject" if role == "subject" else "entrant"
        target = self.plan.subject_stop_m if key == "subject" else self.plan.entrant_start_m
        if station_m != target or not vehicle_class:
            raise ValueError("vehicle construction differs from reviewed plan")
        return self._spawn(key, point_at_station(self.binding, station_m), True)

    def spawn_pedestrian(self, role, station_m):
        if role != "passenger" or station_m != self.plan.subject_stop_m:
            raise ValueError("passenger construction differs from reviewed plan")
        return self._spawn("passenger", self.binding["passenger_spawn_m"], False)

    def set_route(self, actor, destination_m):
        if actor not in self.owned:
            raise ValueError("route actor not owned by this capture")
        if actor.type_id == self.binding["blueprints"]["passenger"]:
            self.routes[actor.id] = tuple(self.binding["passenger_door_m"])
        else:
            if destination_m != self.plan.entrant_destination_m:
                raise ValueError("entrant destination differs from reviewed plan")
            self.routes[actor.id] = point_at_station(self.binding, destination_m)

    def schedule(self, actor, action, at_s):
        if actor not in self.owned or not math.isfinite(float(at_s)) or at_s < 0:
            raise ValueError("Native schedule invalid")
        self.schedule_entries.append({"actor_id": actor.id, "action": action,
                                      "time_s": float(at_s)})

    def restore(self):
        failures = []
        for actor in reversed(self.owned):
            try:
                actor.destroy()
            except Exception as error:
                failures.append(str(error))
        self.owned.clear()
        if self.sync_started:
            try:
                self.world.apply_settings(self.old_settings)
                current = self.world.get_settings()
                if current.synchronous_mode != self.old_settings.synchronous_mode or \
                        current.fixed_delta_seconds != self.old_settings.fixed_delta_seconds:
                    failures.append("world settings restoration readback differs")
            except Exception as error:
                failures.append(str(error))
        if failures:
            raise ValueError("Native restoration failed: " + "; ".join(failures))
        return True


class OriginalAdapter:
    """Single tick owner for live CARLA frames and source-derived observations."""

    VIEWS = ("overview", "approach", "reference_corner", "driver_reference")

    def __init__(self, host, port, config, plan, site_path, *, carla_module=None,
                 client_factory=None, capture_factory=None):
        if carla_module is None:
            import carla
            carla_module = carla
        self.carla = carla_module
        self.client = (client_factory or self.carla.Client)(host, int(port))
        self.client.set_timeout(30.0)
        self.world = NativePlacement(self.client, self.carla, plan, site_path)
        self.config, self.plan = config, plan
        self.capture_factory = capture_factory
        self.actors = None
        self.sensors = {}
        self.camera_queues = {}
        self.encoders = {}
        self.pipeline = None
        self.start_time = None
        self.last_frame = None
        self.sample_index = 0
        self.closed = False
        self.completed = False

    def provenance(self):
        return "original_native"

    def _location(self, actor):
        value = actor.get_transform().location
        return (float(value.x), float(value.y), float(value.z))

    def _speed(self, actor):
        value = actor.get_velocity()
        return math.sqrt(value.x * value.x + value.y * value.y + value.z * value.z)

    def _encoder(self, path, width, height):
        return subprocess.Popen(["ffmpeg", "-hide_banner", "-loglevel", "error",
                                 "-f", "rawvideo", "-pixel_format", "bgra",
                                 "-video_size", f"{width}x{height}", "-framerate", "20",
                                 "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                                stdin=subprocess.PIPE, stdout=subprocess.DEVNULL,
                                stderr=subprocess.PIPE)

    def attach_cameras(self, actors, views):
        if set(views) != set(self.VIEWS) or set(actors) != {"subject", "entrant", "passenger"}:
            raise ValueError("Native participant or four-view construction incomplete")
        self.actors = actors
        output = Path.cwd()
        for spec in self.config["cameras"]:
            view = spec["name"]
            blueprint = self.world.world.get_blueprint_library().find("sensor.camera.rgb")
            if blueprint is None:
                raise ValueError("Native RGB sensor blueprint missing")
            for key, value in (("image_size_x", spec["width"]),
                               ("image_size_y", spec["height"]),
                               ("fov", spec["fov_deg"]), ("sensor_tick", 0)):
                blueprint.set_attribute(key, str(value))
            pose = self.world.binding["camera_poses"][view]
            x, y, z = pose["location_m"]
            pitch, yaw, roll = pose["rotation_deg"]
            transform = self.carla.Transform(self.carla.Location(x=x, y=y, z=z),
                                             self.carla.Rotation(pitch=pitch, yaw=yaw,
                                                                 roll=roll))
            sensor = self.world.world.try_spawn_actor(blueprint, transform)
            if sensor is None or sensor.type_id != "sensor.camera.rgb":
                raise ValueError("Native RGB sensor spawn/readback failed: " + view)
            self.world.owned.append(sensor)
            self.sensors[view] = sensor
            inbox = queue.Queue()
            self.camera_queues[view] = inbox
            sensor.listen(lambda image, target=inbox: target.put(image))
            self.encoders[view] = self._encoder(output / (view + ".mkv"),
                                                spec["width"], spec["height"])
        spec = self.config["cameras"][0]
        self.encoders["raw"] = self._encoder(output / "raw.mkv",
                                              spec["width"], spec["height"])
        if self.capture_factory is None:
            from pipeline_capture import PipelineCapture
            self.capture_factory = PipelineCapture
        self.pipeline = self.capture_factory(self.client, actors["subject"], output,
                                             self.plan.case_id,
                                             required_observations=self.config.get("required_atoms", ()))
        return self.sensors

    def _control_vehicle(self, actor, moving, target_station):
        station = station_of(self.world.binding, self._location(actor))
        if moving and station < target_station - .5:
            control = self.carla.VehicleControl(throttle=.25, brake=0.0)
        else:
            control = self.carla.VehicleControl(throttle=0.0, brake=1.0)
        actor.apply_control(control)

    def request_control(self, actors, plan, index):
        if actors is not self.actors or plan is not self.plan or index < 0:
            raise ValueError("Native control request differs from construction")
        t = index / 20.0
        self._control_vehicle(actors["subject"], t >= plan.subject_departure_s,
                              plan.zone_end_m + 5)
        self._control_vehicle(actors["entrant"], t >= plan.entrant_departure_s,
                              plan.entrant_destination_m)
        passenger = actors["passenger"]
        door = self.world.binding["passenger_door_m"]
        current = self._location(passenger)
        delta = tuple(b - a for a, b in zip(current, door))
        distance = math.dist(current, door)
        walking = plan.passenger_exchange_start_s <= t <= plan.passenger_exchange_end_s
        if walking and distance > .2:
            direction = tuple(d / distance for d in delta)
            speed = min(1.0, distance / .05)
        else:
            direction, speed = (0.0, 0.0, 0.0), 0.0
        passenger.apply_control(self.carla.WalkerControl(
            direction=self.carla.Vector3D(*direction), speed=speed))

    def _camera_image(self, view, frame, time_s):
        deadline = time.monotonic() + 20
        while time.monotonic() < deadline:
            image = self.camera_queues[view].get(timeout=max(.01, deadline-time.monotonic()))
            if image.frame == frame:
                if abs(float(image.timestamp) - time_s) > .005:
                    raise ValueError("Native camera timestamp differs: " + view)
                return image
            if image.frame > frame:
                raise ValueError("Native camera skipped frame: " + view)
        raise ValueError("Native camera timed out: " + view)

    def tick_and_read(self, actors, cameras):
        if actors is not self.actors or cameras is not self.sensors:
            raise ValueError("Native camera/actor identity differs")
        index = self.sample_index
        frame = self.world.world.tick()
        snapshot = self.world.world.get_snapshot()
        if snapshot.frame != frame or (self.last_frame is not None and frame != self.last_frame + 1):
            raise ValueError("Native world frame discontinuity")
        self.last_frame = frame
        time_s = float(snapshot.timestamp.elapsed_seconds)
        if self.start_time is None:
            self.start_time = time_s
        trace = self.pipeline.capture(frame, time_s)
        from PIL import Image
        pixels = {}
        for view in self.VIEWS:
            image = self._camera_image(view, frame, time_s)
            raw = bytes(image.raw_data)
            if self.encoders[view].stdin.write(raw) != len(raw):
                raise ValueError("Native RGB encoder short write: " + view)
            if view == "overview":
                if self.encoders["raw"].stdin.write(raw) != len(raw):
                    raise ValueError("Native raw encoder short write")
            picture = Image.frombytes("RGBA", (image.width, image.height), raw, "raw", "BGRA")
            buffer = io.BytesIO()
            picture.convert("RGB").save(buffer, format="PNG")
            pixels[view] = buffer.getvalue()
        subject, entrant, passenger = (actors[k] for k in ("subject", "entrant", "passenger"))
        subject_station = station_of(self.world.binding, self._location(subject))
        entrant_station = station_of(self.world.binding, self._location(entrant))
        passenger_location = self._location(passenger)
        passenger_station = station_of(self.world.binding, passenger_location)
        door_distance = math.dist(passenger_location, self.world.binding["passenger_door_m"])
        at_door = door_distance <= self.world.binding["observation_tolerances_m"]["door"]
        parent = passenger.get_parent() if hasattr(passenger, "get_parent") else None
        aboard = parent is not None and parent.id == subject.id
        passenger_state = "aboard" if aboard else "at_door" if at_door else "approaching"
        entrant_speed = self._speed(entrant)
        access_range = self.world.binding["observation_tolerances_m"]["access"]
        near_access = self.plan.zone_start_m - access_range <= entrant_station < self.plan.zone_start_m
        entrant_waiting = near_access and entrant_speed < .1
        subject_in_access = _inside_polygon(self._location(subject),
                                             self.world.binding["entrant_access_polygon_m"])
        state = {"case_id": self.plan.case_id, "map_id": self.plan.map_id,
                 "subject_station_m": subject_station, "subject_speed_mps": self._speed(subject),
                 "entrant_station_m": entrant_station, "entrant_speed_mps": entrant_speed,
                 "entrant_waiting": entrant_waiting,
                 "passenger_exchange_active": at_door and not aboard,
                 "passenger_station_m": passenger_station,
                 "passenger_boarding_state": passenger_state,
                 "entrant_access_blocked": near_access and subject_in_access,
                 "entrant_parking_task_active": True}
        self.sample_index += 1
        return {"frame": frame, "time_s": time_s, "state": state,
                "camera_png": pixels, "trace": trace,
                "video_frame": {"video_frame": index,
                                "carla_frame": frame, "time_s": time_s}}

    def finalize_media(self, output, views, mappings):
        if len(mappings) != 900:
            raise ValueError("original video frame map incomplete")
        result = {}
        for view, process in self.encoders.items():
            process.stdin.close()
            stderr = process.stderr.read()
            if process.wait(timeout=180) != 0:
                raise ValueError("Native RGB encoding failed: " + view + ": " +
                                 stderr.decode(errors="replace")[-500:])
            result[view] = Path(output) / (view + ".mkv")
        return result

    def finalize_native_capture(self, output, rows, traces):
        if len(rows) != 900 or self.pipeline is None:
            raise ValueError("original Native graph history incomplete")
        self.pipeline.close(confirmed=True)
        manifest = Path(output) / "capture/manifest.json"
        if json.loads(manifest.read_text()).get("frames") != 900:
            raise ValueError("original Native graph manifest incomplete")
        self.completed = True
        return manifest

    def close(self):
        if self.closed:
            return False
        self.closed = True
        errors = []
        for sensor in self.sensors.values():
            try:
                sensor.stop()
            except Exception as error:
                errors.append(str(error))
        if self.pipeline is not None:
            try:
                self.pipeline.close(confirmed=self.completed and not errors)
            except Exception as error:
                errors.append(str(error))
        for process in self.encoders.values():
            if process.poll() is None:
                process.terminate()
                try:
                    process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    process.kill()
        try:
            self.world.restore()
        except Exception as error:
            errors.append(str(error))
        if errors:
            raise ValueError("Native adapter close failed: " + "; ".join(errors))
        return True


def create_adapter(host, port, config, plan):
    site_path = os.environ.get("SCENARIO_RESTRICTED_ZONE_SITE")
    if not site_path:
        raise ValueError("independent restricted-zone site packet required")
    return OriginalAdapter(host, port, config, plan, site_path)

"""Derive physical timing coverage from sealed original runs, without legal cutoffs."""

import hashlib
import json
from pathlib import Path

from zone_audit import audit_original_frames


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _load_original(attempt, case_id):
    attempt = Path(attempt)
    original = attempt / "original-attempt"
    seal = original / "seal.json"
    if not seal.is_file():
        raise ValueError("sealed original Native attempt missing")
    record = json.loads(seal.read_text())
    if record.get("diagnostic_fixture") is not False:
        raise ValueError("diagnostic attempt cannot establish feasible timing")
    site = original / "site-packet.json"
    if not site.is_file() or record.get("site_packet_sha256") != _sha(site):
        raise ValueError("original site packet missing or stale")
    history = original / "history.jsonl"
    audit_original_frames(history, original / "context.json", seal, case_id)
    packet = json.loads(site.read_text())
    if packet.get("case_id") != case_id or not packet.get("native_binding"):
        raise ValueError("original Native site binding missing or case mismatch")
    identity = {"map_id": packet.get("map_id"),
                "restricted_purpose": packet.get("restricted_purpose"),
                "zone_start_m": packet.get("zone_start_m"),
                "zone_end_m": packet.get("zone_end_m"),
                "sources": {role: item.get("sha256") for role, item in
                            packet.get("sources", {}).items()},
                "native_binding": packet["native_binding"]}
    identity_sha = hashlib.sha256(json.dumps(identity, sort_keys=True).encode()).hexdigest()
    rows = [json.loads(line) for line in history.read_text().splitlines()]
    return identity_sha, rows


def _first(rows, predicate):
    return next((row["time_s"] for row in rows if predicate(row)), None)


def describe_run(rows):
    """Classify observed relative timing; labels are physical, not legal verdicts."""
    exchange_start = _first(rows, lambda row: row["passenger_exchange_active"])
    exchange_end = max((row["time_s"] for row in rows if row["passenger_exchange_active"]),
                       default=None)
    entrant_motion = _first(rows, lambda row: row["entrant_parking_task_active"] and
                            row["entrant_speed_mps"] > .1)
    entrant_wait = _first(rows, lambda row: row["entrant_waiting"])
    access_blocked = _first(rows, lambda row: row["entrant_access_blocked"])
    if exchange_start is None or exchange_end is None or entrant_motion is None:
        raise ValueError("observed exchange or entrant motion absent")
    if entrant_motion < exchange_start:
        relation = "before_exchange"
    elif entrant_motion <= exchange_end:
        relation = "during_exchange"
    else:
        relation = "after_exchange"
    stationary = [row["time_s"] for row in rows if row["subject_speed_mps"] < .1]
    if not stationary:
        raise ValueError("observed subject stop absent")
    return {"relation": relation, "entrant_motion_s": entrant_motion,
            "exchange_start_s": exchange_start, "exchange_end_s": exchange_end,
            "entrant_wait_s": entrant_wait, "access_blocked_s": access_blocked,
            "subject_stationary_span_s": stationary[-1] - stationary[0],
            "legal_temporary": "unresolved_judgment",
            "legal_interference": "unresolved_judgment",
            "legal_about_to_enter": "unresolved_judgment"}


def derive(attempts):
    """Require three distinct source-sealed cases and a common reviewed site."""
    if not isinstance(attempts, dict) or len(attempts) != 3:
        raise ValueError("three original timing cases required")
    sites, runs = set(), {}
    for case_id, attempt in attempts.items():
        site_sha, rows = _load_original(attempt, case_id)
        sites.add(site_sha)
        runs[case_id] = describe_run(rows)
    if len(sites) != 1:
        raise ValueError("original timing cases use different reviewed sites")
    if {run["relation"] for run in runs.values()} != {
            "before_exchange", "during_exchange", "after_exchange"}:
        raise ValueError("original timing cases do not span three physical relations")
    motion = [run["entrant_motion_s"] for run in runs.values()]
    dwell = [run["subject_stationary_span_s"] for run in runs.values()]
    return {"reviewed_site_identity_sha256": next(iter(sites)), "runs": runs,
            "observed_entrant_motion_range_s": [min(motion), max(motion)],
            "observed_subject_stationary_span_range_s": [min(dwell), max(dwell)],
            "coverage_kind": "physical_timing_only",
            "legal_cutoffs": "unresolved_judgment"}
